/*
 * A363406  Start with list L = 1,2,3,4,.... For n = 1,2,3,..., iterate as
 *          follows: let j = L(1) and k = L(j+1), get a(n) = j + k, and remove
 *          j and k from L.
 * https://oeis.org/A363406
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   Sequence generated by L = 1,2,3,4,... For each n: j = L(1) k =
 *            L(j+1) a(n) = j + k remove j and k from L (Offset 1)
 * Range:     u8 n <= 53, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   bit_add, bit_find_kth
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>
#include "../utils/bit_add.h"
#include "../utils/bit_find_kth.h"

/* Main sequence function --------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* offset 1: not defined for n=0   */

    size_t N = (size_t)n;
    size_t M = N * 20 + 100;        /* safe upper bound for all needed values   */
    if (M < 2) M = 2;

    /* Allocate presence array and Fenwick tree */
    unsigned char *present = (unsigned char *)malloc((M + 1) * sizeof(unsigned char));
    int           *bit     = (int *)             malloc((M + 1) * sizeof(int));
    if (!present || !bit) return 0;    /* allocation failure */

    /* Initialize arrays */
    for (size_t i = 1; i <= M; ++i) {
        present[i] = 1;
    }
    for (int i = 0; i <= (int)M; ++i) bit[i] = 0;
    for (size_t i = 1; i <= M; ++i) bit_add(bit, (int)M, (int)i, 1);

    size_t smallest = 1;    /* current L(1) */
    seq_t  result   = 0;

    int M_int = (int)M;     /* for Fenwick tree functions */

    for (size_t step = 1; step <= N; ++step) {
        /* Find current smallest remaining value j */
        while (smallest <= M && !present[smallest]) ++smallest;
        size_t j = smallest;

        int rank = (int)j + 1;
        int kpos = bit_find_kth(bit, M_int, rank);  /* value k = L(j+1) */

        if (step == N) {
            result = (seq_t)j + (seq_t)kpos;
            break;
        }

        /* Remove j */
        present[j] = 0;
        bit_add(bit, M_int, (int)j, -1);

        /* Remove k */
        if ((size_t)kpos != j) {
            present[(size_t)kpos] = 0;
            bit_add(bit, M_int, kpos, -1);
        }
    }

    free(present);
    free(bit);
    return result;
}
